**Debounce** : exécute après pause N sec inactivité. Annule appels précédents. **Throttle** : exécute max 1 fois par N sec.

```python
import asyncio
from functools import wraps
from typing import Callable

def debounce(wait: float):
    def decorator(fn: Callable):
        task: asyncio.Task | None = None
        @wraps(fn)
        async def wrapper(*args, **kwargs):
            nonlocal task
            if task and not task.done():
                task.cancel()
            async def delayed():
                await asyncio.sleep(wait)
                return await fn(*args, **kwargs)
            task = asyncio.create_task(delayed())
            try:
                return await task
            except asyncio.CancelledError:
                return None
        return wrapper
    return decorator

def throttle(interval: float):
    def decorator(fn: Callable):
        last_call = 0.0
        @wraps(fn)
        async def wrapper(*args, **kwargs):
            nonlocal last_call
            now = asyncio.get_event_loop().time()
            if now - last_call < interval:
                return None
            last_call = now
            return await fn(*args, **kwargs)
        return wrapper
    return decorator
```

**Use cases LLM** : debounce search-as-you-type, throttle expensive embeddings.

```python
class TrieNode:
    __slots__ = ('children', 'is_end')
    def __init__(self):
        self.children: dict[str, TrieNode] = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str):
        node = self.root
        for c in word:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
        node.is_end = True

    def autocomplete(self, prefix: str, limit: int = 10) -> list[str]:
        node = self.root
        for c in prefix:
            if c not in node.children:
                return []
            node = node.children[c]
        results = []
        def dfs(node: TrieNode, path: str):
            if len(results) >= limit:
                return
            if node.is_end:
                results.append(path)
            for c, child in node.children.items():
                dfs(child, path + c)
        dfs(node, prefix)
        return results
```

**Complexité** : O(len(word)) insert/search. Mémoire : O(N × L) worst case.

**Variantes** : compressed trie (Radix), DAWG (suffix sharing), avec scoring (BM25-style weighted edges). Production : Elasticsearch completion suggester.

Hash ring pour distribuer N keys sur M nodes. Ajout/suppression node = remap minimal (1/M keys).

```python
import hashlib
import bisect

class ConsistentHash:
    def __init__(self, nodes: list[str], virtual_nodes: int = 100):
        self.virtual_nodes = virtual_nodes
        self.ring: list[int] = []  # sorted positions
        self.position_to_node: dict[int, str] = {}
        for node in nodes:
            self.add_node(node)

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

    def add_node(self, node: str):
        for i in range(self.virtual_nodes):
            pos = self._hash(f"{node}#{i}")
            bisect.insort(self.ring, pos)
            self.position_to_node[pos] = node

    def remove_node(self, node: str):
        for i in range(self.virtual_nodes):
            pos = self._hash(f"{node}#{i}")
            self.ring.remove(pos)
            del self.position_to_node[pos]

    def get_node(self, key: str) -> str:
        if not self.ring:
            raise ValueError("No nodes")
        pos = self._hash(key)
        idx = bisect.bisect_right(self.ring, pos) % len(self.ring)
        return self.position_to_node[self.ring[idx]]
```

**Virtual nodes** : distribue mieux que 1 position/node (évite skew). **Usage** : sharding DB, cache (Memcached), load balancers stateful (sticky sessions).

Distance = nombre min d'opérations (insert, delete, replace) pour transformer s1 en s2.

```python
def edit_distance(s1: str, s2: str) -> int:
    m, n = len(s1), len(s2)
    # dp[i][j] = distance entre s1[:i] et s2[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(
                    dp[i-1][j],    # delete
                    dp[i][j-1],    # insert
                    dp[i-1][j-1],  # replace
                )
    return dp[m][n]
```

**Complexité** : O(m·n) time, O(m·n) space → optimisable O(min(m,n)) avec rolling array.

**Variantes** : Damerau-Levenshtein (+ transposition adjacente). **Use cases** : fuzzy matching, autocorrect, diff tools, dedup near-duplicates dans datasets.

```python
from typing import Any

def json_diff(a: Any, b: Any, path: str = '') -> list[tuple[str, str, Any, Any]]:
    """Return list of (path, op, a_value, b_value). op in {add, remove, change}."""
    diffs = []
    if type(a) != type(b):
        diffs.append((path, 'change', a, b))
        return diffs
    if isinstance(a, dict):
        a_keys, b_keys = set(a.keys()), set(b.keys())
        for k in a_keys - b_keys:
            diffs.append((f"{path}.{k}".lstrip('.'), 'remove', a[k], None))
        for k in b_keys - a_keys:
            diffs.append((f"{path}.{k}".lstrip('.'), 'add', None, b[k]))
        for k in a_keys & b_keys:
            diffs.extend(json_diff(a[k], b[k], f"{path}.{k}".lstrip('.')))
    elif isinstance(a, list):
        for i in range(min(len(a), len(b))):
            diffs.extend(json_diff(a[i], b[i], f"{path}[{i}]"))
        for i in range(len(a), len(b)):
            diffs.append((f"{path}[{i}]", 'add', None, b[i]))
        for i in range(len(b), len(a)):
            diffs.append((f"{path}[{i}]", 'remove', a[i], None))
    else:
        if a != b:
            diffs.append((path, 'change', a, b))
    return diffs
```

**Use cases** : audit config changes, debugging LLM JSON output drift, schema migration. **Library** : `deepdiff` (production-ready, plus complet).
